// === Tab: mySketch ===
/*
Particle Affection (modificato)
- Rotazione continua
- Cambiamento colore dinamico
- Maggiore ingrandimento figura
- Pulsazione della figura
- Colori dinamici per ogni particella
*/

const SPIN_MULTIPLIER = 25;
const MIN_PARTICLE_COUNT = 200;
const MAX_PARTICLE_COUNT = 700;
const MIN_PARTICLE_SIZE = 12;
const MAX_PARTICLE_SIZE = 50;
const MIN_FORCE = 0.1;
const MAX_FORCE = 0.2;
const REPULSION_RADIUS = 100;
const REPULSION_STRENGTH = 0.25;

const DrawTypes = {
    Ellipse: 0,
    Rect: 1,
    Triangle: 2,
};

let particles = [];
let particleCount = 550;
let drawType = DrawTypes.Ellipse;
let globalRotation = 0;

function setup() {
    createCanvas(windowWidth, windowHeight);
    angleMode(RADIANS);
    colorMode(HSB, 360, 100, 100, 255);
    spawnParticles();
}

function draw() {
    background(0);

    textSize(16);
    fill(0, 0, 100);
    textAlign(LEFT);
    text(`Move mouse over heart\nClick/Space to change shape\n+ / - particles`, 50, 50);

    globalRotation += 0.005;

    // Calcola scala pulsante
    let globalScale = 0.6 + 0.6 * pow(sin(frameCount * 0.01), 2);

    translate(width / 2, height / 2);
    rotate(globalRotation);
    scale(globalScale);
    translate(-width / 2, -height / 2);

    particles.forEach((particle, i) => {
        particle.updateColor(frameCount);
        particle.move();
        particle.display();
    });
}

function spawnParticles() {
    particles = [];
    for (let i = 0; i < particleCount; i++) {
        const angle = random(TWO_PI);
        const radius = random(0.4, 1) * 200;
        const x = width / 2 + radius * cos(angle);
        const y = height / 2 - radius * sin(angle);
        particles.push(new Particle(createVector(x, y)));
    }
}

function mouseMoved() {
    particles.forEach((particle) => particle.reactToMouse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

function keyPressed() {
    if (key === '+') {
        particleCount = min(particleCount + 50, MAX_PARTICLE_COUNT);
        spawnParticles();
    } else if (key === '-') {
        particleCount = max(particleCount - 50, MIN_PARTICLE_COUNT);
        spawnParticles();
    } else if (key === ' ') {
        drawType = (drawType + 1) % Object.keys(DrawTypes).length;
    }
}

function mousePressed() {
    if (mouseButton === LEFT) {
        drawType = (drawType + 1) % Object.keys(DrawTypes).length;
    }
}

class Particle {
    constructor(pos) {
        this.pos = pos;
        this.vel = p5.Vector.random2D().mult(random(MIN_FORCE, MAX_FORCE));
        this.size = random(MIN_PARTICLE_SIZE, MAX_PARTICLE_SIZE);
        this.hueOffset = random(360);
    }

    move() {
        this.pos.add(this.vel);
        const d = dist(this.pos.x, this.pos.y, width / 2, height / 2);
        if (d > 200) {
            this.vel.mult(-1);
        }
    }

    reactToMouse(mx, my) {
        var d = dist(this.pos.x, this.pos.y, mx, my);
        if (d < REPULSION_RADIUS) {
            let force = p5.Vector.sub(this.pos, createVector(mx, my)).setMag(REPULSION_STRENGTH);
            this.vel.add(force);
        }
    }

    updateColor(frameCount) {
        let hueValue = (this.hueOffset + frameCount * 2) % 360;
        this.color = color(hueValue, 80, 100, 150);
    }

    display() {
        push();
        translate(this.pos.x, this.pos.y);
        rotate(this.vel.heading() * SPIN_MULTIPLIER);
        fill(this.color);
        noStroke();

        switch (drawType) {
            case DrawTypes.Ellipse:
                ellipse(0, 0, this.size, this.size);
                break;
            case DrawTypes.Rect:
                rect(0, 0, this.size, this.size);
                break;
            case DrawTypes.Triangle:
                triangle(
                    -this.size * 0.5, -this.size * 0.5,
                    0, this.size,
                    this.size * 0.5, -this.size * 0.5
                );
                break;
        }
        pop();
    }
}

